}

interface InventoryService { fetchItem(id: number): Promise<{id:number,name:string}> }
class RemoteInventory implements InventoryService {
  async fetchItem(id: number) { /* network call */ }
}
class CachingProxy implements InventoryService {
  private cache = new Map<number, any>()
  constructor(private real: InventoryService) {}
  async fetchItem(id: number) {
    if (this.cache.has(id)) return this.cache.get(id)
    const item = await this.real.fetchItem(id)
    this.cache.set(id, item)
    return item
  }
}

