interface ApiService { request(path: string): Promise<any> }
class RealApi implements ApiService {
  async request(path: string) { /* perform network request */ }
}
class AuthCachingWrapper implements ApiService {
  private cache = new Map<string, any>()
  constructor(private real: ApiService, private tokenProvider: () => string) {}
  async request(path: string) {
    const token = this.tokenProvider()
    if (this.cache.has(path)) return this.cache.get(path)
    const res = await this.real.request(path)
    this.cache.set(path, res)
    return res
  }
}

